// Package awskms implements vault.KeyBackend with AWS KMS.
//
// It is a separate Go module so that the core SDK takes no AWS dependency. It runs in
// the caller's environment and talks only to the AWS KMS endpoint that the ambient AWS
// configuration selects. It carries no credentials and sends nothing elsewhere.
//
// Every data key is generated by KMS (GenerateDataKey, AES_256) under the key named by
// the key reference. The non-secret encryption context that vault.Seal and vault.Open
// attach to the context (organization and operation identifiers) is passed to KMS,
// which binds it to the wrapped key.
//
// Whether a key is usable, and what a caller may do with it, is decided by AWS KMS and
// the caller's IAM policy. The checks in this package only reject malformed input
// before a request is built and validate the shape of the responses.
package awskms

import (
	"context"
	"errors"
	"fmt"
	"regexp"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/service/kms"
	"github.com/aws/aws-sdk-go-v2/service/kms/types"
	"github.com/aws/smithy-go"

	"github.com/OpenProdkt/governance-sdk-go/governance/vault"
)

const (
	maxKeyRefLength   = 256
	maxWrappedKey     = 4096
	maxContextEntries = 16
	maxContextBytes   = 256
)

var (
	keyARNPattern    = regexp.MustCompile(`^arn:(aws|aws-us-gov|aws-cn):kms:[a-z0-9-]+:[0-9]{12}:key/[a-zA-Z0-9-]+$`)
	aliasARNPattern  = regexp.MustCompile(`^arn:(aws|aws-us-gov|aws-cn):kms:[a-z0-9-]+:[0-9]{12}:alias/[a-zA-Z0-9/_-]+$`)
	aliasPattern     = regexp.MustCompile(`^alias/[a-zA-Z0-9/_-]+$`)
	errorCodePattern = regexp.MustCompile(`^[A-Za-z0-9]{1,64}$`)
)

// KMSClient is the part of the AWS KMS client that Backend uses. *kms.Client satisfies it.
type KMSClient interface {
	GenerateDataKey(ctx context.Context, params *kms.GenerateDataKeyInput, optFns ...func(*kms.Options)) (*kms.GenerateDataKeyOutput, error)
	Decrypt(ctx context.Context, params *kms.DecryptInput, optFns ...func(*kms.Options)) (*kms.DecryptOutput, error)
}

// Backend is a vault.KeyBackend backed by AWS KMS.
type Backend struct {
	client KMSClient
}

var _ vault.KeyBackend = (*Backend)(nil)

// New returns a Backend that calls client. A nil client makes every call fail.
func New(client KMSClient) *Backend {
	return &Backend{client: client}
}

// NewFromConfig builds a Backend with the default AWS configuration chain of the running
// environment: environment variables, shared configuration, and the role or instance
// credentials the environment provides. A region must be configured. The package never
// accepts, reads or stores credentials itself.
func NewFromConfig(ctx context.Context) (*Backend, error) {
	cfg, err := config.LoadDefaultConfig(ctx)
	if err != nil {
		return nil, fmt.Errorf("awskms: load AWS configuration: %w", err)
	}
	if cfg.Region == "" {
		return nil, errors.New("awskms: no AWS region is configured")
	}
	return New(kms.NewFromConfig(cfg)), nil
}

// validKeyRef reports whether keyRef is a KMS key ARN, an alias ARN, or an alias name,
// and whether it is a key ARN.
func validKeyRef(keyRef string) (ok, isKeyARN bool) {
	if keyRef == "" || len(keyRef) > maxKeyRefLength {
		return false, false
	}
	if keyARNPattern.MatchString(keyRef) {
		return true, true
	}
	return aliasARNPattern.MatchString(keyRef) || aliasPattern.MatchString(keyRef), false
}

// kmsContext validates the encryption context attached to ctx and returns it, or nil.
func kmsContext(ctx context.Context) (map[string]string, bool) {
	values := vault.EncryptionContext(ctx)
	if len(values) > maxContextEntries {
		return nil, false
	}
	for k, v := range values {
		if k == "" || v == "" || len(k) > maxContextBytes || len(v) > maxContextBytes {
			return nil, false
		}
	}
	return values, true
}

func errInvalidKeyRef() error {
	return fmt.Errorf("awskms: key reference must be a KMS key ARN, alias ARN or alias name: %w", vault.ErrInvalidInput)
}

// GenerateDataKey asks KMS for a new 32-byte data key under keyRef. It returns the
// plaintext key and the wrapped key.
func (b *Backend) GenerateDataKey(ctx context.Context, keyRef string) ([]byte, []byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, nil, err
	}
	ok, isKeyARN := validKeyRef(keyRef)
	if !ok {
		return nil, nil, errInvalidKeyRef()
	}
	encCtx, ok := kmsContext(ctx)
	if !ok {
		return nil, nil, fmt.Errorf("awskms: encryption context is not acceptable: %w", vault.ErrInvalidInput)
	}
	if b == nil || b.client == nil {
		return nil, nil, errors.New("awskms: no KMS client configured")
	}
	out, err := b.client.GenerateDataKey(ctx, &kms.GenerateDataKeyInput{
		KeyId:             aws.String(keyRef),
		KeySpec:           types.DataKeySpecAes256,
		EncryptionContext: encCtx,
	})
	if out != nil {
		defer zero(out.Plaintext)
	}
	if err != nil {
		return nil, nil, classify(ctx, "GenerateDataKey", err)
	}
	if out == nil || len(out.Plaintext) != vault.DataKeySize {
		return nil, nil, errors.New("awskms: GenerateDataKey returned an unusable data key")
	}
	if len(out.CiphertextBlob) == 0 || len(out.CiphertextBlob) > maxWrappedKey {
		return nil, nil, errors.New("awskms: GenerateDataKey returned an unusable wrapped key")
	}
	if isKeyARN && aws.ToString(out.KeyId) != keyRef {
		return nil, nil, errors.New("awskms: GenerateDataKey response names a different key")
	}
	plaintext := append([]byte(nil), out.Plaintext...)
	wrapped := append([]byte(nil), out.CiphertextBlob...)
	return plaintext, wrapped, nil
}

// Decrypt asks KMS to unwrap a data key under keyRef with the same encryption context
// that was used to wrap it.
//
// When keyRef is a key ARN, the key identifier in the response must equal it. When
// keyRef is an alias, KMS reports the ARN of the key behind the alias, which cannot be
// compared with the alias text, so the response identifier is not compared; the request
// still names the alias as KeyId.
func (b *Backend) Decrypt(ctx context.Context, keyRef string, wrappedKey []byte) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	ok, isKeyARN := validKeyRef(keyRef)
	if !ok {
		return nil, errInvalidKeyRef()
	}
	if len(wrappedKey) == 0 || len(wrappedKey) > maxWrappedKey {
		return nil, fmt.Errorf("awskms: wrapped key has an unusable size: %w", vault.ErrInvalidWrappedKey)
	}
	encCtx, ok := kmsContext(ctx)
	if !ok {
		return nil, fmt.Errorf("awskms: encryption context is not acceptable: %w", vault.ErrInvalidInput)
	}
	if b == nil || b.client == nil {
		return nil, errors.New("awskms: no KMS client configured")
	}
	out, err := b.client.Decrypt(ctx, &kms.DecryptInput{
		CiphertextBlob:      append([]byte(nil), wrappedKey...),
		KeyId:               aws.String(keyRef),
		EncryptionContext:   encCtx,
		EncryptionAlgorithm: types.EncryptionAlgorithmSpecSymmetricDefault,
	})
	if out != nil {
		defer zero(out.Plaintext)
	}
	if err != nil {
		return nil, classify(ctx, "Decrypt", err)
	}
	if out == nil || len(out.Plaintext) != vault.DataKeySize {
		return nil, errors.New("awskms: Decrypt returned an unusable data key")
	}
	if isKeyARN && aws.ToString(out.KeyId) != keyRef {
		return nil, fmt.Errorf("awskms: Decrypt response names a different key: %w", vault.ErrInvalidWrappedKey)
	}
	return append([]byte(nil), out.Plaintext...), nil
}

// classify turns a KMS error into a vault error. The result names the operation and,
// for a service error, its code. It never carries the original message, a request
// body, a key, or a wrapped key.
func classify(ctx context.Context, op string, err error) error {
	if ctxErr := ctx.Err(); ctxErr != nil {
		return fmt.Errorf("awskms: %s: %w", op, ctxErr)
	}
	var disabled *types.DisabledException
	var unavailable *types.KeyUnavailableException
	var invalidState *types.KMSInvalidStateException
	var notFound *types.NotFoundException
	var invalidCiphertext *types.InvalidCiphertextException
	var incorrectKey *types.IncorrectKeyException
	code := errorCode(err)
	switch {
	case errors.As(err, &disabled), errors.As(err, &unavailable), errors.As(err, &invalidState):
		return fmt.Errorf("awskms: %s: key is not usable (%s): %w", op, code, vault.ErrKeyDestroyed)
	case errors.As(err, &notFound):
		return fmt.Errorf("awskms: %s: key does not exist (%s): %w: %w", op, code, vault.ErrKeyDestroyed, vault.ErrKeyNotFound)
	case errors.As(err, &invalidCiphertext), errors.As(err, &incorrectKey):
		return fmt.Errorf("awskms: %s: wrapped key rejected (%s): %w", op, code, vault.ErrInvalidWrappedKey)
	}
	if code != "" {
		return fmt.Errorf("awskms: %s failed (%s)", op, code)
	}
	return fmt.Errorf("awskms: %s failed", op)
}

// errorCode returns the service error code when it has a plain, bounded shape.
func errorCode(err error) string {
	var apiErr smithy.APIError
	if errors.As(err, &apiErr) && errorCodePattern.MatchString(apiErr.ErrorCode()) {
		return apiErr.ErrorCode()
	}
	return ""
}

func zero(b []byte) {
	for i := range b {
		b[i] = 0
	}
}
